BEGIN;SET ROLE postgres;SELECT set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);UPDATE sigo_correccion_inicial.configuracion SET habilitada=true;DO $g$ DECLARE r record;BEGIN FOR r IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('corregir_unidad_inicial_sigo','previsualizar_correccion_unidad_inicial_sigo','guardar_producto_medida_revision_sigo','listar_revisiones_unidad_producto_sigo') LOOP EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',r.oid::regprocedure);END LOOP;END $g$;SET ROLE authenticated;SELECT public.corregir_unidad_inicial_sigo('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','70000000-0000-0000-0000-000000000001',public.previsualizar_correccion_unidad_inicial_sigo('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','kg')->>'snapshot','CONFIRMO_CARGA_INICIAL_SIN_MOVIMIENTOS_Y_VALORES_YA_EN_UNIDAD_DESTINO','kg');SELECT public.configurar_archivo_producto_sigo('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004',true);DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.listar_productos_sigo('10000000-0000-0000-0000-000000000001') WHERE id='30000000-0000-0000-0000-000000000004') OR NOT EXISTS(SELECT 1 FROM public.listar_inventario_productos_sigo('10000000-0000-0000-0000-000000000001') WHERE id='30000000-0000-0000-0000-000000000004' AND archivado_comercial AND unidad_revision='1') THEN RAISE EXCEPTION 'ARCHIVE_CATALOG_ASSERT';END IF;END $$;ROLLBACK;